/// Temporary environment placeholders used until Firebase is configured.
abstract final class Env {
  static const String firebaseAndroidKey = '';
  static const String firebaseIosKey = '';
  static const String firebaseAndroidAppId = '';
  static const String firebaseIosAppId = '';
  static const String firebaseMessagingSenderId = '';
  static const String firebaseProjectId = '';
  static const String firebaseStorageBucket = '';
}
